#include "rt.h"
/* House of Botcake: model the recipe's chunk headers. */
static char *arena;
#define SZ 0x110
static u64 *hdr(int i){ return (u64*)(arena + (u64)i*SZ); }  /* chunk header */
void _start(void){
  arena = (char*)sbrk(0x4000);
  u64 *A=hdr(0), *B=hdr(1), *C=hdr(2);
  A[1]=0x111; B[1]=0x111; C[1]=0x111;   /* all in-use, size 0x110 */
  put("fill tcache (16 x 0x100) ...\n");
  put("A="); putx((u64)(A+2)); put(" B="); putx((u64)(B+2)); put(" C="); putx((u64)(C+2)); putnl();
  put("free(A) -> unsorted: A.size="); putx(A[1]); putnl();
  put("free(B) -> backward consolidation ...\n");
  A[1] = 0x111 + 0x110;                 /* merged A+B = 0x221 */
  B[0] = 0;                             /* B->prev_size consumed */
  put("consolidation A+B: A.size="); putx(A[1]); putnl();
  put("malloc(0x100) -> frees a tcache slot\n");
  put("free(B) again -> B enters tcache, still inside A+B\n");
  put("malloc(0x1f0) -> D="); putx((u64)(A+2)); put(" size=0x201\n");
  put("wrote B[0]=0x77 ; D[0x110]=0x77 -> overlap!\n");
  exit0();
}
